// BlogServer is the server API for Blog service.
// All implementations must embed UnimplementedBlogServer
// for forward compatibility.
//
// 个人博客服务（文章/评论/点赞/分类/标签/主题/页面/协议开通/插件版本/图片上传/站管管理/举报）
// 实现位于 user/internal/service/blog*.go（由手写 HTTP 路由迁移而来）。
// 路径前缀：/v1/user/blog/*
type BlogServer interface {
	// 公开：按用户名列出文章（含作者与博客壳配置；JWT 可选，有则识别作者）
	ListByUsername(context.Context, *ListByUsernameReq) (*ListByUsernameRes, error)
	// 公开：文章详情（id 或 username+slug；password/unlockToken 解锁）
	GetArticle(context.Context, *GetArticleReq) (*GetArticleRes, error)
	// 公开：密码文解锁，返回 unlockToken
	Unlock(context.Context, *UnlockReq) (*UnlockRes, error)
	// 公开：精选文章（推荐）
	Recommend(context.Context, *RecommendReq) (*RecommendRes, error)
	// 公开：主站博客广场文章流
	Plaza(context.Context, *PlazaReq) (*PlazaRes, error)
	// 公开：最近有公开文的作者（广场侧栏）
	Authors(context.Context, *AuthorsReq) (*AuthorsRes, error)
	// 公开：作者公开分类列表（仅含 >0 篇公开文章的分类）
	ListCategoriesPublic(context.Context, *ListCategoriesPublicReq) (*ListCategoriesPublicRes, error)
	// 公开：作者公开文标签聚合
	ListTagsPublic(context.Context, *ListTagsPublicReq) (*ListTagsPublicRes, error)
	// 公开：已发布且显示在导航的页面列表
	PageListPublic(context.Context, *PageListPublicReq) (*PageListPublicRes, error)
	// 公开：已发布页面详情
	PageGetPublic(context.Context, *PageGetPublicReq) (*PageGetPublicRes, error)
	// 公开（登录可带 liked）：文章评论列表（顶层分页 + 嵌套 replies）
	ListComments(context.Context, *ListCommentsReq) (*ListCommentsRes, error)
	// 公开：博客主题状态（enabled/themeId/colorScheme/subtitle/socialLinks/槽位）
	ThemeStatus(context.Context, *ThemeStatusReq) (*ThemeStatusRes, error)
	// 登录：创建文章
	Create(context.Context, *CreateReq) (*CreateRes, error)
	// 登录：更新文章（作者/站管/审核员）
	Update(context.Context, *UpdateReq) (*UpdateRes, error)
	// 登录：删除文章（级联清理评论/点赞/标签/UV）
	Delete(context.Context, *DeleteReq) (*DeleteRes, error)
	// 登录：我的文章列表
	Mine(context.Context, *MineReq) (*MineRes, error)
	// 登录：作者统计（汇总 + top 文章）
	Analytics(context.Context, *AnalyticsReq) (*AnalyticsRes, error)
	// 登录：我的页面列表
	PageMine(context.Context, *PageMineReq) (*PageMineRes, error)
	// 登录：创建页面
	PageCreate(context.Context, *PageCreateReq) (*PageCreateRes, error)
	// 登录：更新页面
	PageUpdate(context.Context, *PageUpdateReq) (*PageUpdateRes, error)
	// 登录：删除页面
	PageDelete(context.Context, *PageDeleteReq) (*PageDeleteRes, error)
	// 登录：页面排序
	PageReorder(context.Context, *PageReorderReq) (*PageReorderRes, error)
	// 登录：创建分类
	CategoryCreate(context.Context, *CategoryCreateReq) (*CategoryCreateRes, error)
	// 登录：更新分类（name/sortOrder 省略保留原值）
	CategoryUpdate(context.Context, *CategoryUpdateReq) (*CategoryUpdateRes, error)
	// 登录：删除分类（默认分类不可删；文章改挂默认分类）
	CategoryDelete(context.Context, *CategoryDeleteReq) (*CategoryDeleteRes, error)
	// 登录：我的分类列表（自动确保默认分类存在）
	CategoryMine(context.Context, *CategoryMineReq) (*CategoryMineRes, error)
	// 登录：发表评论
	CommentCreate(context.Context, *CommentCreateReq) (*CommentCreateRes, error)
	// 登录：删除评论（作者/文章作者/站管；级联删除子树）
	CommentDelete(context.Context, *CommentDeleteReq) (*CommentDeleteRes, error)
	// 登录：评论点赞 toggle
	CommentLikeToggle(context.Context, *CommentLikeToggleReq) (*CommentLikeToggleRes, error)
	// 登录：文章点赞 toggle
	LikeToggle(context.Context, *LikeToggleReq) (*LikeToggleRes, error)
	// 登录：保存主题配置（themeId + social links + MD 槽位）
	ThemeConfigSave(context.Context, *ThemeConfigSaveReq) (*ThemeConfigSaveRes, error)
	// 站管：主题开关（user|batch|all，遗留能力）
	ThemeEnable(context.Context, *ThemeEnableReq) (*ThemeEnableRes, error)
	// 公开：开通协议正文 + 当前用户开通状态（可匿名看正文）
	AgreementGet(context.Context, *AgreementGetReq) (*AgreementGetRes, error)
	// 登录：当前用户开通状态
	ActivationStatus(context.Context, *ActivationStatusReq) (*ActivationStatusRes, error)
	// 登录：签署协议并开通博客
	Activate(context.Context, *ActivateReq) (*ActivateRes, error)
	// 登录：更新互动邮件通知偏好
	NotifyPref(context.Context, *NotifyPrefReq) (*NotifyPrefRes, error)
	// 公开：Obsidian 插件当前版本元信息（插件检查更新）
	ObsidianPluginLatest(context.Context, *ObsidianPluginLatestReq) (*ObsidianPluginLatestRes, error)
	// 发布脚本/站管：登记插件当前版本（X-Plugin-Publish-Token 或站管 JWT）
	ObsidianPluginPublish(context.Context, *ObsidianPluginPublishReq) (*ObsidianPluginPublishRes, error)
	// 登录：当前用户图片上传能力状态
	ImageUploadStatus(context.Context, *ImageUploadStatusReq) (*ImageUploadStatusRes, error)
	// 登录：申请图片上传权限
	ImageUploadApply(context.Context, *ImageUploadApplyReq) (*ImageUploadApplyRes, error)
	// 登录：批量确认图床 URL/object key/content hash 是否仍在资产表
	BlogImagesCheck(context.Context, *BlogImagesCheckReq) (*BlogImagesCheckRes, error)
	// 站管/博客管理：开关作者图片上传
	AdminImageUpload(context.Context, *AdminImageUploadReq) (*AdminImageUploadRes, error)
	// 站管/博客管理：图片上传申请列表
	AdminImageUploadRequests(context.Context, *AdminImageUploadRequestsReq) (*AdminImageUploadRequestsRes, error)
	// 站管/博客管理：审核图片上传申请
	AdminImageUploadReview(context.Context, *AdminImageUploadReviewReq) (*AdminImageUploadReviewRes, error)
	// 站管：博客数据看板概览
	AdminOverview(context.Context, *AdminOverviewReq) (*AdminOverviewRes, error)
	// 站管：已开通作者列表
	AdminAuthors(context.Context, *AdminAuthorsReq) (*AdminAuthorsRes, error)
	// 站管：文章审查列表（含 private/password）
	AdminArticles(context.Context, *AdminArticlesReq) (*AdminArticlesRes, error)
	// 站管/博客审核：文章审核（approve|reject|pending|feature|unfeature）
	AdminModerate(context.Context, *AdminModerateReq) (*AdminModerateRes, error)
	// 仅站点管理员：全站图片资产（mode=all|cleanup）
	AdminBlogImages(context.Context, *AdminBlogImagesReq) (*AdminBlogImagesRes, error)
	// 仅站点管理员：删除单张图片（状态已变化返回 409）
	AdminBlogImageDelete(context.Context, *AdminBlogImageDeleteReq) (*AdminBlogImageDeleteRes, error)
	// 仅站点管理员：按快照批量删除候选图片（快照不一致返回 409）
	AdminBlogImagesDeleteBatch(context.Context, *AdminBlogImagesDeleteBatchReq) (*AdminBlogImagesDeleteBatchRes, error)
	// 登录：举报博客文章
	Report(context.Context, *ReportReq) (*ReportRes, error)
	// 举报处理台（content.report.handle）：举报列表
	ReportList(context.Context, *ReportListReq) (*ReportListRes, error)
	// 举报处理台（content.report.handle）：处理举报
	ReportHandle(context.Context, *ReportHandleReq) (*ReportHandleRes, error)
	mustEmbedUnimplementedBlogServer()
}

